def import_recurring_bills(apps, schema_editor):
    from django.utils import timezone
    database = schema_editor.connection.alias
    Schedule = apps.get_model("finance", "RecurringSchedule")
    Subscription = apps.get_model("finance", "Subscription")
    Price = apps.get_model("finance", "SubscriptionPrice")
    Cycle = apps.get_model("finance", "SubscriptionCycle")
    Allocation = apps.get_model("finance", "SubscriptionPaymentAllocation")
    Expense = apps.get_model("finance", "Transaction")
    for schedule in Schedule.objects.using(database).filter(kind__in=("bill", "subscription", "payment"), settlement_kind="expense", system_key__isnull=True).iterator():
        subscription, _ = Subscription.objects.using(database).get_or_create(schedule_id=schedule.pk, defaults={
            "service_type": "variable" if schedule.variable_amount else "fixed", "status": "active" if schedule.active else "paused", "created_by_id": schedule.created_by_id})
        if not schedule.variable_amount and schedule.amount:
            Price.objects.using(database).get_or_create(subscription_id=subscription.pk, effective_date=timezone.localdate(),
                defaults={"amount": schedule.amount, "imported": True, "created_by_id": schedule.created_by_id})
        for deadline in schedule.deadlines.using(database).filter(asset_financing__isnull=True, cash_loan__isnull=True, loan__isnull=True).iterator():
            expense = Expense.objects.using(database).filter(deadline_id=deadline.pk).first()
            actual = (deadline.amount if deadline.amount is not None else expense.amount) if expense else deadline.amount if schedule.variable_amount else None
            cycle, _ = Cycle.objects.using(database).get_or_create(deadline_id=deadline.pk, defaults={"subscription_id": subscription.pk,
                "actual_amount": actual, "amount_source": "actual" if actual is not None else "unconfirmed" if schedule.variable_amount else "fixed",
                "confirmed_at": expense.created_at if expense else deadline.updated_at if actual is not None else None, "created_by_id": deadline.created_by_id})
            if expense:
                Allocation.objects.using(database).get_or_create(transaction_id=expense.pk, defaults={"cycle_id": cycle.pk,
                    "request_id": expense.request_id, "created_by_id": expense.created_by_id})


